// Merge: start from snapshot rows, append any new bookings not yet in snapshot
// (and drop any cleaning-table stubs that leaked into older snapshots).
const snapRows = (snap.rows || []).filter(function (r) { return !_opsIsCleanStub(r); });
const snapAptIds = new Set(snapRows.map(r => r.aptId||r.aptName));
const newRows = freshRows.filter(r => !snapAptIds.has(r.aptId||r.aptName));

if (newRows.length > 0) {
  // New bookings arrived since snapshot — toast notification
  setTimeout(() => {
    if (typeof toast === 'function')
      toast(newRows.length + ' νέα checkout προστέθηκαν από τελευταία αποθήκευση', 'info');
  }, 300);
}

// Snapshots saved before these kinds existed carry none of the flags, and a
// booking can change after a snapshot is taken - so re-detect on every load.
// Anything set by hand (<kind>Manual) always beats detection.
const _fresh = {};
freshRows.forEach(function (r) { _fresh[r.aptId||r.aptName] = r; });
const _merged = [...snapRows, ...newRows].map(function (r) {
  const f = _fresh[r.aptId||r.aptName];
  const out = { ...r };
  OPS_KINDS.forEach(function (k) {
    const auto = f ? !!f[k.key] : !!r[k.key];
    out[k.key] = (r[k.manual] === true) ? true : (r[k.manual] === false) ? false : auto;
  });
  out.isOwner = f ? !!f.isOwner : !!r.isOwner;
  if (!f) {
    // Booking gone (cancelled checkout, deleted check-in). Keep only rows the
    // operator pinned by hand.
    const keep = !!r.checkinManual || (typeof OPS_KINDS !== 'undefined' && OPS_KINDS.some(function (k) { return r[k.manual]; }));
    return keep ? out : null;
  }
  // Same-day check-in status used to freeze in the day's snapshot as
  // "Δεν ξέρουμε ακόμα". Refresh from live bookings unless the operator
  // toggled the cell by hand. A checkout with no arrival must not keep a
  // frozen 7-night / 6-people check-in (Athenian Cedar 15/8).
  if (f && !r.checkinManual) {
    if (f.checkinSameDay === 'yes' || f.checkinSameDay === 'checkin_only') {
      out.checkinSameDay = f.checkinSameDay;
      out.nextNights = f.nextNights;
      out.nextGuest = f.nextGuest || '';
      if (f.people != null && f.people !== '') out.people = f.people;
      else if (!out.people) out.people = '';
      out.isCheckinOnly = !!f.isCheckinOnly;
      if (f.checkinSameDay === 'checkin_only') out.checkoutGuest = '';
    } else {
      out.checkinSameDay = f.checkinSameDay || 'unknown';
      out.nextNights = null;
      out.nextGuest = '';
      out.people = '';
      out.isCheckinOnly = false;
      if (f.checkoutGuest != null) out.checkoutGuest = f.checkoutGuest;
    }
  }
  return out;
}).filter(function (row) { return !!row; });
return {
  rows: _opsOrder(_merged),
  notes: snap.notes||'',
  savedAt: snap.savedAt,
};

