// Live Hosthub bookings are the source of check-ins/checkouts. The day's
// saved row only overlays operator work (cleaners, comments, toggles).
const snapRows = (snap.rows || []).filter(function (r) { return !_opsIsCleanStub(r); });
const snapByKey = {};
snapRows.forEach(function (r) { snapByKey[String(r.aptId || r.aptName)] = r; });
const OPS_OVERLAY = ['cleanerName','cleanerNames','cleanDone','cleanTask','cleanTaskNote','comments','alreadyCleaned','cleanedDate','lateCheckout','checkoutRequested','arrivalTime','parkBed','earlyCheckin','isPriority','priorityManual','checkinManual'];

const _merged = freshRows.map(function (f) {
  const r = snapByKey[String(f.aptId || f.aptName)] || {};
  const out = Object.assign({}, f);
  if (snapByKey[String(f.aptId || f.aptName)]) {
    OPS_OVERLAY.forEach(function (k) {
      if (r[k] != null) out[k] = r[k];
    });
  }
  OPS_KINDS.forEach(function (k) {
    const auto = !!f[k.key];
    out[k.key] = (r[k.manual] === true) ? true : (r[k.manual] === false) ? false : auto;
    if (r[k.manual] != null) out[k.manual] = r[k.manual];
  });
  out.isOwner = !!f.isOwner;
  // Same-day check-in status used to freeze in the day's snapshot as
  // "Δεν ξέρουμε ακόμα". Refresh from live bookings unless the operator
  // toggled the cell by hand. A checkout with no arrival must not keep a
  // frozen 7-night / 6-people check-in (Athenian Cedar 15/8).
  if (f && !r.checkinManual) {
    if (f.checkinSameDay === 'yes' || f.checkinSameDay === 'checkin_only') {
      out.checkinSameDay = f.checkinSameDay;
      out.nextNights = f.nextNights;
      out.nextGuest = f.nextGuest || '';
      if (f.people != null && f.people !== '') out.people = f.people;
      else if (!out.people) out.people = '';
      out.isCheckinOnly = !!f.isCheckinOnly;
      if (f.checkinSameDay === 'checkin_only') out.checkoutGuest = '';
      else out.checkoutGuest = f.checkoutGuest || '';
    } else {
      out.checkinSameDay = f.checkinSameDay || 'unknown';
      out.nextNights = null;
      out.nextGuest = '';
      out.people = '';
      out.isCheckinOnly = false;
      if (f.checkoutGuest != null) out.checkoutGuest = f.checkoutGuest;
    }
  }
  return out;
}).filter(function (row) { return !!row; });
snapRows.forEach(function (r) {
  const key = String(r.aptId || r.aptName);
  if (freshRows.some(function (f) { return String(f.aptId || f.aptName) === key; })) return;
  const keep = !!r.checkinManual || (typeof OPS_KINDS !== 'undefined' && OPS_KINDS.some(function (k) { return r[k.manual]; }));
  if (keep) _merged.push(r);
});
return {
  rows: _opsOrder(_merged),
  notes: snap.notes||'',
  savedAt: snap.savedAt,
};

